"""Normalise slash-separated paths.

Pure standard-library implementation. The rules below differ from
``os.path``/``pathlib`` semantics, so those modules are deliberately avoided.
"""


def normalize(path):
    """Normalise a slash-separated path string.

    See TASK.md for the exact rules.
    """
    absolute = path.startswith("/")
    # Split on every slash; runs of slashes yield empty segments which are
    # dropped, together with "." segments, by rule 2.
    segments = [s for s in path.split("/") if s not in ("", ".")]

    kept_parents = []  # leading ".." kept in relative paths (rule 3)
    stack = []

    for seg in segments:
        if seg == "..":
            if stack:
                stack.pop()
            elif not absolute:
                kept_parents.append("..")
            # absolute path: ".." at the root is dropped (rule 3)
            continue
        stack.append(seg)

    if absolute:
        # Root stays "/" (rule 4); otherwise one leading slash (rule 1).
        return "/" + "/".join(stack)

    if not stack and not kept_parents:
        # Empty relative path is "." (rule 5).
        return "."

    # Relative path: leading kept ".." first, then the remaining segments.
    return "/".join(kept_parents + stack)


def join(base, *parts):
    """Apply ``parts`` to ``base`` from left to right, then normalise."""
    current = base
    for part in parts:
        if part == "":
            # An empty part changes nothing (rule 9).
            continue
        if part.startswith("/"):
            # An absolute part replaces everything before it (rule 7).
            current = part
        elif current == "":
            current = part
        else:
            current = current + "/" + part
    return normalize(current)
